import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    H,W=len(g),len(g[0])
    vals={x for row in g for x in row}
    seedv=min(vals,-(min(vals))) if False else min([v for v in vals if v!=0], key=lambda v: sum(row.count(v) for row in g))
    # seed color = non-zero color whose count is small (shape); others are noise
    cnt={v:g[0].count(v)+sum(row.count(v) for row in g[1:]) for v in vals}
    seedv=min(cnt,key=cnt.get)   # rarest non-zero = seed
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]==seedv]
    mr=min(p[0] for p in pts); mc=min(p[1] for p in pts)
    shape={(a-mr,b-mc) for a,b in pts}
    ch=set()
    for di in range(-H,H+1):
        for dj in range(-W,W+1):
            cells={(a+di,b+dj) for a,b in shape}
            if any(not(0<=a<H and 0<=b<W) for a,b in cells) or any(g[a][b]!=0 for a,b in cells): continue
            ch|=cells
    return [[seedv if (i,j) in ch else g[i][j] for j in range(W)] for i in range(H)]
for name in ['1','2','3','4']:
    gi=G[f'Demo pair {name} input']; go=G[f'Demo pair {name} output']
    assert f(gi)==go, name
print('all demos pass')
out=f(G['Test input'])
print(json.dumps(out))
